import requests, json, collections, numpy as np, pandas as pd, math
import matplotlib.pyplot as plt

def stream(q, fields="accession,ft_signal,ft_transmem,sequence"):
    u=f"https://rest.uniprot.org/uniprotkb/stream?query={q}&fields={fields}&format=json"
    return requests.get(u,timeout=300).json()["results"]
sp_set = stream("(organism_id:9606)+AND+(reviewed:true)+AND+(ft_signal:*)")
sa_set = stream('(organism_id:9606)+AND+(reviewed:true)+AND+(ft_transmem:"Signal-anchor+for+type+II+membrane+protein")')

AAs="ACDEFGHIKLMNPQRSTVWY"; aidx={a:i for i,a in enumerate(AAs)}
exp=[]
for e in sp_set:
    sq=e["sequence"]["value"]
    for f in e.get("features",[]):
        if f["type"]!="Signal": continue
        L=f["location"]
        if L["start"].get("value") is None or L["end"].get("value") is None: continue
        end=L["end"]["value"]
        if end>=13 and end+2<=len(sq) and "ECO:0000269" in {ev.get("evidenceCode") for ev in f.get("evidences",[])}:
            exp.append(sq[end-13:end+2])
bg=collections.Counter()
for e in sp_set: bg.update(e["sequence"]["value"])
t=sum(bg[a] for a in AAs); bg={a:bg[a]/t for a in AAs}
pwm=np.zeros((15,20))
for j in range(15):
    c=collections.Counter(s[j] for s in exp)
    for i,a in enumerate(AAs):
        pwm[j,i]=math.log(((c[a]+1.0)/(len(exp)+20.0))/bg[a])
def sc(seq,cut):
    s=seq[cut-13:cut+2]
    return None if (len(s)!=15 or any(a not in aidx for a in s)) else sum(pwm[j,aidx[s[j]]] for j in range(15))
def best_cut(seq,lo=14,hi=45):
    v=[(sc(seq,c),c) for c in range(lo,hi+1) if sc(seq,c) is not None]; return max(v)

kd={'A':1.8,'R':-4.5,'N':-3.5,'D':-3.5,'C':2.5,'Q':-3.5,'E':-3.5,'G':-0.4,'H':-3.2,'I':4.5,
    'L':3.8,'K':-3.9,'M':1.9,'F':2.8,'P':-1.6,'S':-0.8,'T':-0.7,'W':-0.9,'Y':-1.3,'V':4.2}
def hfeat(seq,n=45,thr=1.0,win=7):
    s=seq[:n]
    sm=[np.mean([kd.get(a,0) for a in s[max(0,i-win//2):i+win//2+1]]) for i in range(len(s))]
    best=cur=0
    for v in sm:
        cur=cur+1 if v>thr else 0; best=max(best,cur)
    return best,float(np.max(sm))
def ncharge(seq,k=8):   # net charge of first k residues (positive-inside / n-region)
    return sum(1 for a in seq[:k] if a in "KR")-sum(1 for a in seq[:k] if a in "DE")

rows=[]
def add(name,seq,cls):
    s,c=best_cut(seq); hl,hm=hfeat(seq)
    rows.append(dict(name=name,cls=cls,pwm=s,cut=c,P1=seq[c-1],P3=seq[c-3],hlen=hl,hmax=hm,nq=ncharge(seq)))

accs={"AADACL2":"Q6P093","AADAC":"P22760","NCEH1":"Q6PIU2","AADACL3":"Q5VUY0","AADACL4":"Q5VUY2"}
qseq={s:requests.get(f"https://rest.uniprot.org/uniprotkb/{a}.fasta",timeout=60).text.split("\n",1)[1].replace("\n","") for s,a in accs.items()}
for s,v in qseq.items(): add(s,v,"QUERY")
for e in sp_set:
    sq=e["sequence"]["value"]
    if len(sq)>60 and any(f["type"]=="Signal" and "ECO:0000269" in {ev.get("evidenceCode") for ev in f.get("evidences",[])} for f in e.get("features",[])):
        add(e["primaryAccession"],sq,"SP_exp")
# matched signal-anchor set: TM must START within first 15 residues (same architecture as AADAC family)
nmatched=0
for e in sa_set:
    sq=e["sequence"]["value"]
    tms=[f for f in e.get("features",[]) if f["type"]=="Transmembrane" and "Signal-anchor" in f.get("description","")]
    if not tms or len(sq)<=60: continue
    st=tms[0]["location"]["start"]["value"]
    if st<=15:
        add(e["primaryAccession"],sq,"SA_shortNtail"); nmatched+=1
    else:
        add(e["primaryAccession"],sq,"SA_longNtail")
df=pd.DataFrame(rows)
print(df.cls.value_counts().to_string())

q=df[df.cls=="QUERY"].set_index("name")
ref={c:df[df.cls==c] for c in ["SP_exp","SA_shortNtail"]}
print("\n%-10s %7s %5s %2s %2s %5s %4s | pctile in SP_exp | pctile in SA_shortNtail"%("gene","PWM","cut","P1","P3","hlen","n+"))
for g in accs:
    r=q.loc[g]
    p_sp=100*(ref["SP_exp"].pwm<r.pwm).mean(); p_sa=100*(ref["SA_shortNtail"].pwm<r.pwm).mean()
    print(f"{g:<10} {r.pwm:7.2f} {r.cut:5d} {r.P1:>2} {r.P3:>2} {r.hlen:5.0f} {r.nq:4.0f} |   {p_sp:5.1f}%          |   {p_sa:5.1f}%")
print("\nreference medians [IQR]:")
for c in ["SP_exp","SA_shortNtail","SA_longNtail"]:
    d=df[df.cls==c]
    print(f"  {c:15s} n={len(d):4d}  PWM {d.pwm.median():6.2f} [{d.pwm.quantile(.25):.2f},{d.pwm.quantile(.75):.2f}]"
          f"  hlen {d.hlen.median():4.0f} [{d.hlen.quantile(.25):.0f},{d.hlen.quantile(.75):.0f}]"
          f"  P1=A/G/S/C/T: {100*d.P1.isin(list('AGSCT')).mean():5.1f}%")
from scipy import stats
u=stats.mannwhitneyu(ref["SP_exp"].pwm, ref["SA_shortNtail"].pwm)
print("\nMann-Whitney SP_exp vs SA_shortNtail PWM: U=%.0f p=%.3g"%(u.statistic,u.pvalue))
globals()['df']=df; globals()['qseq']=qseq; globals()['pwm']=pwm

fig,ax=plt.subplots(1,2,figsize=(13,5.2))
for c,col,lab in [("SP_exp","#3a7ca5","Experimental cleaved signal peptide (n=%d)"%len(ref["SP_exp"])),
                  ("SA_shortNtail","#d1495b","Type II signal anchor, TM starts <=15 (n=%d)"%len(ref["SA_shortNtail"]))]:
    ax[0].hist(df[df.cls==c].pwm,bins=40,density=True,alpha=.55,color=col,label=lab)
cols={"AADACL2":"black","AADAC":"#8d6a9f","NCEH1":"#2e8b57","AADACL3":"#c08552","AADACL4":"#7f7f7f"}
for g in accs:
    ax[0].axvline(q.loc[g,"pwm"],color=cols[g],lw=2,ls="--")
    ax[0].text(q.loc[g,"pwm"],ax[0].get_ylim()[1]*(0.95-0.09*list(accs).index(g)),"  "+g,color=cols[g],fontsize=9,weight="bold")
ax[0].set_xlabel("von Heijne cleavage-site PWM score (best site, res 14-45)")
ax[0].set_ylabel("density"); ax[0].legend(fontsize=8,loc="upper left")
ax[0].set_title("AADACL2 cleavage-site context is not signal-peptide-like")

ax[1].scatter(ref["SP_exp"].pwm,ref["SP_exp"].hlen,s=7,alpha=.35,color="#3a7ca5",label="SP (experimental)")
ax[1].scatter(ref["SA_shortNtail"].pwm,ref["SA_shortNtail"].hlen,s=7,alpha=.45,color="#d1495b",label="type II signal anchor")
for g in accs:
    ax[1].scatter(q.loc[g,"pwm"],q.loc[g,"hlen"],s=120,marker="*",color=cols[g],edgecolor="k",zorder=5)
    ax[1].annotate(g,(q.loc[g,"pwm"],q.loc[g,"hlen"]),textcoords="offset points",xytext=(6,4),fontsize=9,weight="bold")
ax[1].set_xlabel("cleavage-site PWM score"); ax[1].set_ylabel("longest hydrophobic stretch in res 1-45 (KD>1, w=7)")
ax[1].legend(fontsize=8); ax[1].set_title("Two-feature separation")
plt.tight_layout(); plt.show()
